    /// </summary>
    [CliOption("--tags")]
    public IEnumerable<string>? Tags { get; set; }

    /// <summary>
    /// If this is an alarm based on an anomaly detection model, make this value match the ID of the ANOMALY_DETECTION_BAND function. For an example of how to use this parameter, see the Anomaly Detec- tion Model Alarm example on this page. If your alarm uses this parameter, it cannot have Auto Scaling ac- tions. Constraints: o min: 1 o max: 255
    /// </summary>
    [CliOption("--threshold-metric-id")]
    public string? ThresholdMetricId { get; set; }

    /// <summary>
    /// The evaluation window that the alarm uses to select the range of metric data that it evaluates. Specify either a sliding window or a wall clock window. If you omit this parameter, the alarm uses a sliding window. A sliding window advances each time the alarm is evaluated, forming a rolling time window. A wall clock window aligns the evaluated range to fixed clock boundaries, such as the top of the hour or the start of the day. You can use EvaluationWindow with any type of metric alarm except alarms that are based on a PromQL query. For more information, see Alarm evaluation windows in the CloudWatch User Guide . NOTE: This is a Tagged Union structure. Only one of the following top level keys can be set: WallClockWindow, SlidingWindow. WallClockWindow -&gt; (structure) A wall clock window, which aligns the evaluated range to fixed clock boundaries that match the alarm's period, such as the top of the hour, midnight, or the start of the calendar week. Timezone -&gt; (string) The time zone to use when the alarm aligns the evaluation window to clock boundaries. You can specify an IANA time zone name (for example, America/New_York ), a fixed UTC offset (for example, +05:30 ), or an offset-prefixed identifier (for example, UTC+05:30 ). The offset must be aligned to a multi- ple of 5 minutes. If you don't specify a time zone, Cloud- Watch uses UTC . The time zone affects window alignment for all periods, in- cluding periods of one hour or shorter. Constraints: o min: 1 o max: 50 SlidingWindow -&gt; (structure) A sliding window, which advances each time the alarm is evalu- ated, forming a rolling time window. This is the default evalua- tion window. Shorthand Syntax: WallClockWindow={Timezone=string},SlidingWindow={} JSON Syntax: { "WallClockWindow": { "Timezone": "string" }, "SlidingWindow": { } }
    /// </summary>
    [CliOption("--evaluation-window")]
    public string? EvaluationWindow { get; set; }

    /// <summary>
    /// The warm-up configuration for the alarm. A warm-up period delays alarm evaluation after you create or update the alarm. The warm-up period reduces alarm noise from missing data while a new resource or service starts publishing metrics. For more information, see Alarm warm-up periods in the Amazon Cloud- Watch User Guide . WarmUpPeriodDurationInMinutes -&gt; (integer) [required] The length of the warm-up period, in minutes. After you create or update the alarm, the alarm stays in INSUFFICIENT_DATA for this duration. During this time, the alarm does not perform alarm actions. You can change this value at any time, including after the warm-up period ends. If you change it after the warm-up period ends, the new value does not restart the warm-up period. Constraints: o min: 1 o max: 2880 OnlyStartEvaluatingAfterWarmUpPeriodEnds -&gt; (boolean) Specifies whether the alarm waits for the full warm-up period before it starts to evaluate. The default is false . If true , the alarm waits the entire WarmUpPeriodDurationInMinutes before it starts to evaluate, even if metric data arrives earlier. If false , the alarm ends the warm-up period early. Evaluation be- gins as soon as the alarm has enough metric data to fill its evaluation window. Shorthand Syntax: WarmUpPeriodDurationInMinutes=integer,OnlyStartEvaluatingAfterWarmUpPeriodEnds=boolean JSON Syntax: { "WarmUpPeriodDurationInMinutes": integer, "OnlyStartEvaluatingAfterWarmUpPeriodEnds": true|false }
    /// </summary>
    [CliOption("--warm-up-configuration")]
    public string? WarmUpConfiguration { get; set; }

    /// <summary>
    /// The evaluation criteria for the alarm. For each PutMetricAlarm oper- ation, you must specify either MetricName , a Metrics array, or an EvaluationCriteria . If you use the EvaluationCriteria parameter, you cannot include the Namespace , MetricName , Dimensions , Period , Unit , Statistic , ExtendedStatistic , Metrics , Threshold , ComparisonOperator , ThresholdMetricId , EvaluationPeriods , or DatapointsToAlarm parame- ters of PutMetricAlarm in the same operation. Instead, all evalua- tion parameters are defined within this structure. For an example of how to use this parameter, see the PromQL alarm example on this page. NOTE: This is a Tagged Union structure. Only one of the following top level keys can be set: PromQLCriteria. PromQLCriteria -&gt; (structure) The PromQL criteria for the alarm evaluation. Query -&gt; (string) [required] The PromQL query that the alarm evaluates. The query must re- turn a result of vector type. Each entry in the vector result represents an alarm contributor. Constraints: o min: 1 o max: 10000 PendingPeriod -&gt; (integer) The duration, in seconds, that a contributor must be continu- ously breaching before it transitions to the ALARM state. Constraints: o min: 0 o max: 86400 RecoveryPeriod -&gt; (integer) The duration, in seconds, that a contributor must continu- ously not be breaching before it transitions back to the OK state. Constraints: o min: 0 o max: 86400 Shorthand Syntax: PromQLCriteria={Query=string,PendingPeriod=integer,RecoveryPeriod=integer} JSON Syntax: { "PromQLCriteria": { "Query": "string", "PendingPeriod": integer, "RecoveryPeriod": integer } }
    /// </summary>
    [CliOption("--evaluation-criteria")]
    public string? EvaluationCriteria { get; set; }

    /// <summary>
    /// The frequency, in seconds, at which the alarm is evaluated. Valid values are 10, 20, 30, and any multiple of 60. This parameter is required for alarms that use EvaluationCriteria , and cannot be specified for alarms configured with MetricName or Metrics . Constraints: o min: 10 o max: 3600
    /// </summary>
    [CliOption("--evaluation-interval")]
    public int? EvaluationInterval { get; set; }

    [CliOption("--cli-input-json")]
    public string? CliInputJson { get; set; }

    [CliOption("--generate-cli-skeleton")]
    public string? GenerateCliSkeleton { get; set; }

